-- V49 — English document templates for Egypt (iso_code = 'EG')
-- Updates html_content and description for all 6 standard templates scoped to the EG entity.
-- Template lookup names remain unchanged (they are keys used by PdfDocumentService.renderByName).
-- Known limitation: date variables (startDateMoisAn, startDate, document.date) still return
-- French month names from the backend resolver; a follow-up backend change is needed for
-- fully English dates. Contract duration labels are also French-keyed in the resolver.

-- ── 1. Employment Certificate ─────────────────────────────────────────────
UPDATE [dbo].[document_templates]
SET
    [description]  = N'Standard employment certificate (open-ended / fixed-term contract)',
    [html_content] = N'<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">{{company.name}}</div><div class="company-sub">Engineering Consulting Firm</div></div></div><div class="doc-date">Cairo, {{document.date}}</div><div class="doc-title">Employment Certificate</div><hr class="title-underline"><p class="body-text">I, the undersigned, <strong>{{company.dgName}}</strong>, holder of National ID No. <strong>{{company.dgCin}}</strong> issued in {{company.dgCinCity}} on {{company.dgCinDate}}, acting as <strong>{{company.dgTitle}}</strong> of <strong>{{company.name}}</strong>,</p><p class="body-text">hereby certify that <strong>{{employee.civilite}} {{employee.fullName}}</strong>, holder of National ID No. <strong>{{employee.cin}}</strong> issued in {{employee.cinCity}} on {{employee.cinDate}}, holds the position of <strong>{{employee.position}}</strong> within our company since <strong>{{employee.startDateMoisAn}}</strong>, under a <strong>{{employee.contractDuration}}</strong> employment contract.</p><p class="body-text">This certificate is issued upon the request of the interested party for all legal purposes.</p><div class="signature-block"><p><strong>{{company.name}}</strong></p><p>{{company.dgTitle}}</p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>{{company.name}}</strong> &mdash; Engineering Consulting Firm</div><div style="margin-top:1.5mm;">Page 1 of 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref: {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Verification Code: {{document.verificationCode}}</div></div></div></body></html>',
    [variables]    = N'["employee.civilite","employee.fullName","employee.cin","employee.cinCity","employee.cinDate","employee.position","employee.startDateMoisAn","employee.contractDuration","company.name","company.dgName","company.dgTitle","company.dgCin","company.dgCinCity","company.dgCinDate","document.date","document.ref","document.verificationCode"]',
    [updated_at]   = SYSDATETIMEOFFSET()
WHERE [pays_id] IN (SELECT id FROM [dbo].[pays] WHERE iso_code = N'EG')
  AND [name] = N'Attestation de Travail';
GO

-- ── 2. Salary Certificate ─────────────────────────────────────────────────
UPDATE [dbo].[document_templates]
SET
    [description]  = N'Salary certificate showing annual gross and net salary amounts (EGP)',
    [html_content] = N'<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">{{company.name}}</div><div class="company-sub">Engineering Consulting Firm</div></div></div><div class="doc-date">Cairo, {{document.date}}</div><div class="doc-title">Salary Certificate</div><hr class="title-underline"><p class="body-text">I, the undersigned, <strong>{{company.dgName}}</strong>, holder of National ID No. <strong>{{company.dgCin}}</strong> issued in {{company.dgCinCity}} on {{company.dgCinDate}}, acting as <strong>{{company.dgTitle}}</strong> of <strong>{{company.name}}</strong>;</p><p class="body-text">hereby certify that <strong>{{employee.civilite}} {{employee.fullName}}</strong>, holder of National ID No. <strong>{{employee.cin}}</strong> issued in {{employee.cinCity}} on {{employee.cinDate}}, employed within our company since <strong>{{employee.startDateMoisAn}}</strong>, receives an estimated Annual Gross Salary of <strong>{{employee.salaireBrutAnnuel}} Egyptian Pounds (EGP)</strong>, i.e. <strong>{{employee.salaireBrutAnnuelEnLettres}}</strong>. This is equivalent to an Annual Net Salary of <strong>{{employee.salaireNetAnnuel}} Egyptian Pounds (EGP)</strong>.</p><p class="body-text">This certificate is issued upon request for all legal purposes.</p><div class="signature-block"><p><strong>The {{company.dgTitle}}</strong></p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>{{company.name}}</strong> &mdash; Engineering Consulting Firm</div><div style="margin-top:1.5mm;">Page 1 of 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref: {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Verification Code: {{document.verificationCode}}</div></div></div></body></html>',
    [variables]    = N'["employee.civilite","employee.fullName","employee.cin","employee.cinCity","employee.cinDate","employee.startDateMoisAn","employee.salaireBrutAnnuel","employee.salaireBrutAnnuelEnLettres","employee.salaireNetAnnuel","company.name","company.dgName","company.dgTitle","company.dgCin","company.dgCinCity","company.dgCinDate","document.date","document.ref","document.verificationCode"]',
    [updated_at]   = SYSDATETIMEOFFSET()
WHERE [pays_id] IN (SELECT id FROM [dbo].[pays] WHERE iso_code = N'EG')
  AND [name] = N'Attestation de Salaire';
GO

-- ── 3. Certificate of Non-Benefit from Loan ───────────────────────────────
-- Employee self-declares; management countersigns on behalf of the company.
UPDATE [dbo].[document_templates]
SET
    [description]  = N'Certificate declaring the employee has no outstanding loan or advance from the employer',
    [html_content] = N'<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">{{company.name}}</div><div class="company-sub">Engineering Consulting Firm</div></div></div><div class="doc-date">Cairo, {{document.date}}</div><div class="doc-title">Certificate of Non-Benefit from Loan</div><hr class="title-underline"><p class="body-text">I, the undersigned, <strong>{{employee.civilite}} {{employee.fullName}}</strong>, holder of National ID No. <strong>{{employee.cin}}</strong> issued in {{employee.cinCity}} on {{employee.cinDate}}, employed at <strong>{{company.name}}</strong> (Engineering Consulting Firm) and residing in {{employee.city}},</p><p class="body-text">hereby freely and solemnly certify that I do not currently benefit from any loan, credit, or financial advance of any nature from my employer, <strong>{{company.name}}</strong>, as of this date.</p><p class="body-text">This certificate is issued upon request for all legal purposes.</p><div class="signature-block"><p><strong>On behalf of {{company.name}}</strong></p><p>Management</p><br><br><p><em>Stamp and Signature</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>{{company.name}}</strong> &mdash; Engineering Consulting Firm</div><div style="margin-top:1.5mm;">Page 1 of 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref: {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Verification Code: {{document.verificationCode}}</div></div></div></body></html>',
    [variables]    = N'["employee.city","employee.civilite","employee.fullName","employee.cin","employee.cinCity","employee.cinDate","company.name","company.dgTitle","document.date","document.ref","document.verificationCode"]',
    [updated_at]   = SYSDATETIMEOFFSET()
WHERE [pays_id] IN (SELECT id FROM [dbo].[pays] WHERE iso_code = N'EG')
  AND [name] = N'Attestation de Non-Benefice de Pret';
GO

-- ── 4. Permanent Employment Certificate ───────────────────────────────────
UPDATE [dbo].[document_templates]
SET
    [description]  = N'Certificate confirming conversion to permanent (open-ended) employment contract',
    [html_content] = N'<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">{{company.name}}</div><div class="company-sub">Engineering Consulting Firm</div></div></div><div class="doc-date">Cairo, {{document.date}}</div><div class="doc-title">Permanent Employment Certificate</div><hr class="title-underline"><p class="body-text">I, the undersigned, <strong>{{company.dgName}}</strong>, holder of National ID No. <strong>{{company.dgCin}}</strong> issued in {{company.dgCinCity}} on {{company.dgCinDate}}, acting as <strong>{{company.dgTitle}}</strong> of <strong>{{company.name}}</strong>,</p><p class="body-text">hereby certify that <strong>{{employee.civilite}} {{employee.fullName}}</strong>, holder of National ID No. <strong>{{employee.cin}}</strong> issued in {{employee.cinCity}} on {{employee.cinDate}}, has been confirmed on a permanent basis in the position of <strong>{{employee.position}}</strong> within our company, effective <strong>{{employee.titularisationDate}}</strong>.</p><p class="body-text"><strong>{{employee.civilite}} {{employee.fullName}}</strong> is accordingly entitled to an open-ended employment contract in accordance with applicable labour legislation.</p><p class="body-text">This certificate is issued upon the request of the interested party for all legal purposes.</p><div class="signature-block"><p><strong>{{company.name}}</strong></p><p>{{company.dgTitle}}</p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>{{company.name}}</strong> &mdash; Engineering Consulting Firm</div><div style="margin-top:1.5mm;">Page 1 of 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref: {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Verification Code: {{document.verificationCode}}</div></div></div></body></html>',
    [variables]    = N'["employee.civilite","employee.fullName","employee.cin","employee.cinCity","employee.cinDate","employee.position","employee.titularisationDate","company.name","company.dgName","company.dgTitle","company.dgCin","company.dgCinCity","company.dgCinDate","document.date","document.ref","document.verificationCode"]',
    [updated_at]   = SYSDATETIMEOFFSET()
WHERE [pays_id] IN (SELECT id FROM [dbo].[pays] WHERE iso_code = N'EG')
  AND [name] = N'Attestation de Titularisation';
GO

-- ── 5. Salary Bank Account Certificate ───────────────────────────────────
UPDATE [dbo].[document_templates]
SET
    [description]  = N'Certificate confirming the bank account to which the employee salary is transferred',
    [html_content] = N'<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .company-block { text-align: right; } .company-name-hdr { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; font-weight: bold; color: #1e3a5f; } .company-sub { font-family: Arial, Helvetica, sans-serif; font-size: 8.5pt; color: #555; margin-top: 1mm; } .doc-date { text-align: right; font-size: 10.5pt; margin-bottom: 16mm; } .doc-title { font-family: Arial, Helvetica, sans-serif; font-size: 14pt; font-weight: bold; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 3mm; } .title-underline { display: block; width: 68%; border: none; border-top: 2px solid #000; margin: 0 auto 10mm; } .body-text { line-height: 1.9; text-align: justify; margin: 3.5mm 0; } .bank-block { margin: 4mm 0 4mm 28mm; line-height: 2.2; } .bank-row { display: flex; gap: 6mm; align-items: baseline; } .bank-label { font-weight: bold; min-width: 18mm; } .signature-block { margin-top: 14mm; text-align: right; line-height: 2; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="company-block"><div class="company-name-hdr">{{company.name}}</div><div class="company-sub">Engineering Consulting Firm</div></div></div><div class="doc-date">Cairo, {{document.date}}</div><div class="doc-title">Salary Bank Account Certificate</div><hr class="title-underline"><p class="body-text">I, the undersigned, <strong>{{company.dgName}}</strong>, holder of National ID No. <strong>{{company.dgCin}}</strong> issued in {{company.dgCinCity}} on {{company.dgCinDate}}, acting as <strong>{{company.dgTitle}}</strong> of <strong>{{company.name}}</strong>,</p><p class="body-text">hereby certify that the monthly salary of <strong>{{employee.civilite}} {{employee.fullName}}</strong>, holding the position of <strong>{{employee.position}}</strong> within our company since <strong>{{employee.startDate}}</strong>, is transferred to the following bank account:</p><div class="bank-block"><div class="bank-row"><span class="bank-label">Bank:</span><span>{{employee.bank}}</span></div><div class="bank-row"><span class="bank-label">Account No.:</span><span>{{employee.rib}}</span></div><div class="bank-row"><span class="bank-label">IBAN:</span><span>{{employee.iban}}</span></div></div><p class="body-text">The monthly salary transfer is made exclusively to this account.</p><p class="body-text">This certificate is issued upon the request of the interested party for all legal purposes.</p><div class="signature-block"><p><strong>{{company.name}}</strong></p><p>{{company.dgTitle}}</p><br><br><p><em>{{company.dgName}}</em></p></div><div class="footer-rule"></div><div class="footer"><div><strong>{{company.name}}</strong> &mdash; Engineering Consulting Firm</div><div style="margin-top:1.5mm;">Page 1 of 1 &nbsp;&nbsp;|&nbsp;&nbsp; Ref: {{document.ref}} &nbsp;&nbsp;|&nbsp;&nbsp; Verification Code: {{document.verificationCode}}</div></div></div></body></html>',
    [variables]    = N'["employee.civilite","employee.fullName","employee.position","employee.startDate","employee.bank","employee.rib","employee.iban","company.name","company.dgName","company.dgTitle","company.dgCin","company.dgCinCity","company.dgCinDate","document.date","document.ref","document.verificationCode"]',
    [updated_at]   = SYSDATETIMEOFFSET()
WHERE [pays_id] IN (SELECT id FROM [dbo].[pays] WHERE iso_code = N'EG')
  AND [name] = N'Attestation de Domiciliation de Salaire';
GO

-- ── 6. ARX France Invitation Letter ──────────────────────────────────────
-- Sender info and trip details injected via extraCtx at render time:
--   sender.name, sender.title, sender.address, sender.city
--   employee.birthDate, employee.birthCity, employee.passportNumber
--   trip.startDate, trip.endDate, trip.hotel
UPDATE [dbo].[document_templates]
SET
    [description]  = N'Professional invitation letter for French visa (French Consulate General in Cairo)',
    [html_content] = N'<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: Georgia, ''Times New Roman'', Times, serif; font-size: 11pt; color: #000; } .page { width: 210mm; min-height: 297mm; padding: 18mm 22mm 30mm; position: relative; background: #fff; } .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 14mm; } .arx-logo-text { font-family: Arial, Helvetica, sans-serif; font-size: 30pt; font-weight: 900; color: #1e3a5f; line-height: 1; letter-spacing: -1px; } .arx-tagline { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #666; letter-spacing: 4px; margin-top: 2mm; } .sender-block { text-align: right; font-size: 10.5pt; line-height: 1.7; } .date-recipient-row { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10mm; } .doc-date { font-size: 10.5pt; } .recipient-block { text-align: left; font-size: 10.5pt; line-height: 1.7; } .subject-line { margin: 6mm 0 10mm; font-size: 10.5pt; line-height: 1.7; } .salutation { margin-bottom: 6mm; font-size: 11pt; } .body-text { line-height: 1.9; text-align: justify; margin: 4mm 0; font-size: 10.5pt; } .signature-block { margin-top: 14mm; text-align: left; line-height: 2; font-size: 10.5pt; } .footer-rule { position: absolute; bottom: 20mm; left: 22mm; right: 22mm; height: 1px; background: #ccc; } .footer { position: absolute; bottom: 6mm; left: 22mm; right: 22mm; font-family: Arial, Helvetica, sans-serif; font-size: 7pt; color: #888; text-align: center; line-height: 1.7; }</style></head><body><div class="page"><div class="header"><div><div class="arx-logo-text">ARX</div><div class="arx-tagline">S M A R T &nbsp; M I N D S</div></div><div class="sender-block"><strong>{{sender.name}}</strong><br>{{sender.title}}<br>{{sender.address}}<br>{{sender.city}}</div></div><div class="date-recipient-row"><div class="doc-date">{{sender.city}}, {{document.date}}</div><div class="recipient-block"><strong>French Consulate General in Cairo</strong><br>1 Latin America St.,<br>Cairo, Egypt</div></div><div class="subject-line"><strong>Subject:</strong> Professional invitation for an on-site project meeting<br><strong>Copy:</strong> {{company.name}}</div><p class="salutation">Dear Consul General,</p><p class="body-text">Acting in my capacity as <strong>{{sender.title}}</strong> of <strong>Arx France</strong>, I hereby inform you of my intention to invite the following foreign national to France: <strong>{{employee.civilite}} {{employee.fullName}}</strong>, born on <strong>{{employee.birthDate}}</strong> in <strong>{{employee.birthCity}}</strong>, holder of passport No. <strong>{{employee.passportNumber}}</strong>, currently residing in EGYPT, {{employee.city}}, and holding the position of <strong>{{employee.position}}</strong>.</p><p class="body-text">This invitation is strictly professional in nature and is planned for a period of 30 days, from <strong>{{trip.startDate}}</strong> to <strong>{{trip.endDate}}</strong>. Its purpose is the execution and supervision of engineering studies for the <strong>Grand Paris Line 15</strong> project, carried out by {{company.name}} on behalf of Arx France.</p><p class="body-text">The presence of <strong>{{employee.civilite}} {{employee.fullName}}</strong> is required to coordinate the studies, attend project meetings, and participate in the client audit meeting with Arx France. This assignment cannot be performed remotely or postponed.</p><p class="body-text">During the stay, <strong>{{employee.civilite}} {{employee.fullName}}</strong> will reside at <strong>{{trip.hotel}}</strong>.</p><p class="body-text">All costs related to the stay in France of <strong>{{employee.civilite}} {{employee.fullName}}</strong> will be fully covered by their employer, <strong>{{company.name}}</strong>, domiciled in Cairo, Egypt.</p><p class="body-text">I remain at your disposal for any further information and extend to you, Dear Consul General, my highest regards.</p><div class="signature-block"><strong>{{sender.name}}</strong><br>{{sender.title}}</div><div class="footer-rule"></div><div class="footer"><div><strong>{{company.name}}</strong> &mdash; Engineering Consulting Firm</div><div style="margin-top:1.5mm;">Page 1 of 1</div></div></div></body></html>',
    [variables]    = N'["employee.civilite","employee.fullName","employee.position","employee.city","employee.birthDate","employee.birthCity","employee.passportNumber","company.name","sender.name","sender.title","sender.address","sender.city","trip.startDate","trip.endDate","trip.hotel","document.date"]',
    [updated_at]   = SYSDATETIMEOFFSET()
WHERE [pays_id] IN (SELECT id FROM [dbo].[pays] WHERE iso_code = N'EG')
  AND [name] = N'Lettre d''Invitation ARX France';
GO
